  }

  private renderQueue(board: boolean) {
    const filtersLoading = this.carregarFiltrosEquipeStatus === 'loading';
    const tasksLoading = this.listarTarefasEquipeStatus === 'loading' || this.pageStatus === 'loading';
    const rows = this.tarefas?.items ?? [];
    return html`
      <section data-organism-id="tarefasEquipe" class="px-4 pb-8 pt-3">
        <div class="flex gap-2">
          <button type="button" class="min-h-11 flex-1 rounded-lg border border-[var(--button-secondary-border,currentColor)] bg-[var(--button-secondary-bg,transparent)] px-3 text-sm font-medium text-[var(--button-secondary-text,currentColor)] focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" @click=${() => this.setScenario('fila')}>${this.msg.listView}</button>
          <button type="button" class="min-h-11 flex-1 rounded-lg border border-[var(--button-secondary-border,currentColor)] bg-[var(--button-secondary-bg,transparent)] px-3 text-sm font-medium text-[var(--button-secondary-text,currentColor)] focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" @click=${() => this.setScenario('quadro')}>${this.msg.boardView}</button>
        </div>
        <div class="mt-4 rounded-xl border border-[var(--border-subtle,currentColor)] bg-[var(--surface-bg,transparent)] p-3">
          <p class="mb-3 text-sm font-semibold text-[var(--text-strong,currentColor)]">${this.msg.filters}</p>
          <div class="flex flex-wrap gap-2">
            ${(['aFazer', 'emAndamento', 'emRevisao', 'concluida', 'cancelada'] as TaskStatus[]).map((status) => html`
              <button type="button" class="min-h-11 rounded-full border border-[var(--border-default,currentColor)] px-3 text-xs font-medium focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)] ${this.filtrosEquipe.status === status ? 'bg-[var(--selected-bg,transparent)] text-[var(--selected-text,currentColor)] border-[var(--selected-border,currentColor)]' : 'bg-[var(--surface-alt-bg,transparent)]'}" @click=${() => { this.setFiltrosEquipe({ ...this.filtrosEquipe, status }); this.listarTarefasEquipe(); }}>${this.msg[STATUS_KEY[status]]}</button>
            `)}
          </div>
          <div class="mt-3 grid gap-3">
            <label class="grid gap-1 text-sm font-medium">${this.msg.list}
              <select class="min-h-11 rounded-lg border border-[var(--border-default,currentColor)] bg-[var(--input-bg,transparent)] px-3 focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" .value=${this.filtrosEquipe.listaId ?? ''} ?disabled=${filtersLoading} @change=${(e: Event) => this.setFiltrosEquipe({ ...this.filtrosEquipe, listaId: (e.target as HTMLSelectElement).value || null })}>
                <option value="">${this.msg.allLists}</option>
                ${this.listas.map((item) => html`<option value=${item.id}>${item.nome}</option>`)}
              </select>
            </label>
            <label class="grid gap-1 text-sm font-medium">${this.msg.assignee}
              <select class="min-h-11 rounded-lg border border-[var(--border-default,currentColor)] bg-[var(--input-bg,transparent)] px-3 focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" .value=${this.filtrosEquipe.responsavelId ?? ''} ?disabled=${filtersLoading} @change=${(e: Event) => this.setFiltrosEquipe({ ...this.filtrosEquipe, responsavelId: (e.target as HTMLSelectElement).value || null })}>
                <option value="">${this.msg.allAssignees}</option>
                ${this.carregarFiltrosEquipeParticipantes.map((item) => html`<option value=${item.id}>${item.details.identification.name}</option>`)}
              </select>
            </label>
            <label class="grid gap-1 text-sm font-medium">${this.msg.priority}
              <select class="min-h-11 rounded-lg border border-[var(--border-default,currentColor)] bg-[var(--input-bg,transparent)] px-3 focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" .value=${this.filtrosEquipe.prioridade ?? ''} @change=${(e: Event) => this.setFiltrosEquipe({ ...this.filtrosEquipe, prioridade: ((e.target as HTMLSelectElement).value || null) as TaskPriority | null })}>
                <option value="">${this.msg.allPriorities}</option>
                ${(['baixa', 'media', 'alta'] as TaskPriority[]).map((priority) => html`<option value=${priority}>${this.msg[PRIORITY_KEY[priority]]}</option>`)}
              </select>
            </label>
            <groupenterdateinterval--ml-date-interval-presets .startDate=${this.filtrosEquipe.prazoDe} .endDate=${this.filtrosEquipe.prazoAte} .locale=${'pt-BR'} .loading=${tasksLoading} @change=${(e: CustomEvent<{ startDate: string | null; endDate: string | null }>) => this.setFiltrosEquipe({ ...this.filtrosEquipe, prazoDe: e.detail.startDate, prazoAte: e.detail.endDate })}>
              <Label>${this.msg.duePeriod}</Label><LabelStart>${this.msg.dueFrom}</LabelStart><LabelEnd>${this.msg.dueUntil}</LabelEnd>
            </groupenterdateinterval--ml-date-interval-presets>
          </div>
          <div class="mt-3 flex gap-2">
            <button type="button" class="min-h-11 flex-1 rounded-lg bg-[var(--button-primary-bg,transparent)] px-3 text-sm font-semibold text-[var(--button-primary-text,currentColor)] focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" ?disabled=${tasksLoading} @click=${() => this.listarTarefasEquipe()}>${this.msg.applyFilters}</button>
            <button type="button" class="min-h-11 rounded-lg border border-[var(--button-secondary-border,currentColor)] px-3 text-sm font-medium focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" @click=${() => { this.setFiltrosEquipe({ listaId: null, responsavelId: null, prioridade: null, status: null, prazoDe: null, prazoAte: null }); this.listarTarefasEquipe(); }}>${this.msg.clearFilters}</button>
          </div>
          ${this.carregarFiltrosEquipeError ? html`<div class="mt-3 flex items-center justify-between gap-2 text-sm text-[var(--status-error-text,currentColor)]" role="alert"><span>${this.msg.filterOptionsError}</span><button type="button" class="min-h-11 underline" @click=${() => this.carregarFiltrosEquipe()}>${this.msg.reloadFilters}</button></div>` : ''}
        </div>
        ${this.listarTarefasEquipeError ? html`<div class="mt-4 rounded-xl border border-[var(--status-error-text,currentColor)] bg-[var(--surface-bg,transparent)] p-4" role="alert"><p>${this.msg.loadError}</p><button type="button" class="mt-2 min-h-11 font-semibold underline" @click=${() => this.listarTarefasEquipe()}>${this.msg.tryAgain}</button></div>` : ''}
        ${tasksLoading ? html`<p class="py-8 text-center text-sm text-[var(--text-muted,currentColor)]" aria-live="polite">${this.msg.loadingTasks}</p>` : ''}
        ${!tasksLoading && !this.listarTarefasEquipeError && rows.length === 0 ? html`<p class="py-10 text-center text-sm text-[var(--text-muted,currentColor)]">${this.msg.emptyTasks}</p>` : ''}
        <div class=${board ? 'mt-4 grid gap-3' : 'mt-4 divide-y divide-[var(--border-subtle,currentColor)] rounded-xl border border-[var(--border-subtle,currentColor)] bg-[var(--surface-bg,transparent)]'}>
          ${rows.map((row) => this.renderTaskRow(row, board))}
        </div>
      </section>
    `;
  }

  private renderTaskRow(row: TarefaResumo, board: boolean) {
    return html`<button type="button" class="w-full text-left focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)] ${board ? 'rounded-xl border border-[var(--border-subtle,currentColor)] bg-[var(--surface-bg,transparent)] p-4' : 'p-4'}" @click=${() => { this.obterTarefaEquipe(row.id); this.setScenario('detalhe'); }}>
      <div class="flex items-start justify-between gap-3"><span class="font-semibold text-[var(--text-strong,currentColor)]">${row.titulo}</span><span class="shrink-0 text-right text-xs font-medium ${row.details.atrasada ? 'text-[var(--status-error-text,currentColor)]' : row.details.venceHoje ? 'text-[var(--status-warning-text,currentColor)]' : 'text-[var(--text-muted,currentColor)]'}">${row.details.atrasada ? this.msg.overdue : row.details.venceHoje ? this.msg.dueToday : row.prazo ? formatDate(row.prazo) : this.msg.noDueDate}</span></div>
      <div class="mt-2 flex items-center justify-between gap-3"><span class="rounded-full bg-[var(--status-neutral-bg,transparent)] px-2 py-1 text-xs font-medium text-[var(--status-neutral-text,currentColor)]">${this.msg[STATUS_KEY[row.status]]}</span><span class="text-xs text-[var(--text-muted,currentColor)]">${this.msg[PRIORITY_KEY[row.prioridade]]}</span></div>
      <div class="mt-2 text-xs text-[var(--text-muted,currentColor)]">${this.msg.actsNow}: ${row.quemAgeAgoraNome ?? this.msg.noOneActsNow}</div>
    </button>`;
  }

  private renderDetail() {
    const task = this.tarefa;
    if (this.obterTarefaEquipeStatus === 'loading') return html`<p class="p-6 text-center text-sm text-[var(--text-muted,currentColor)]" aria-live="polite">${this.msg.loadingTasks}</p>`;
    if (this.obterTarefaEquipeError) return html`<div class="m-4 rounded-xl border border-[var(--status-error-text,currentColor)] p-4" role="alert"><p>${this.msg.openingError}</p><button type="button" class="mt-3 min-h-11 font-semibold underline" @click=${() => this.obterTarefaEquipe(this.selectedTarefa)}>${this.msg.tryAgain}</button></div>`;
    if (!task) return html`<p class="p-6 text-center text-sm text-[var(--text-muted,currentColor)]">${this.msg.selectTask}</p>`;
