          <CardContent>
            <dl class="grid grid-cols-2 gap-x-4 gap-y-3 text-sm"><div><dt class="text-[var(--text-muted,currentColor)]">${this.msg.assignee}</dt><dd class="font-medium">${task.participante.details.identification.name}</dd></div><div><dt class="text-[var(--text-muted,currentColor)]">${this.msg.dueDate}</dt><dd class="font-medium">${task.prazo ? formatDate(task.prazo) : this.msg.noDueDate}</dd></div><div><dt class="text-[var(--text-muted,currentColor)]">${this.msg.actsNow}</dt><dd class="font-medium">${task.quemAgeAgoraNome ?? this.msg.noOneActsNow}</dd></div><div><dt class="text-[var(--text-muted,currentColor)]">${this.msg.checklistProgress}</dt><dd class="font-medium">${task.details.progressoChecklist}</dd></div><div><dt class="text-[var(--text-muted,currentColor)]">${this.msg.subtasks}</dt><dd class="font-medium">${task.details.quantidadeSubtarefas}</dd></div><div><dt class="text-[var(--text-muted,currentColor)]">${this.msg.createdAt}</dt><dd class="font-medium">${formatDate(task.criadaEm)}</dd></div><div class="col-span-2"><dt class="text-[var(--text-muted,currentColor)]">${this.msg.createdBy}</dt><dd class="font-medium">${task.criadorNome}</dd></div></dl>
            <div class="mt-4"><p class="text-sm font-semibold">${this.msg.description}</p><p class="mt-1 whitespace-pre-wrap text-sm text-[var(--text-default,currentColor)]">${task.details.descricao ?? this.msg.noDescription}</p></div>
          </CardContent>
        </groupviewcard--ml-vertical-card>
        <div class="mt-5" data-organism-id="tarefaAcoes">
          ${this.trocarResponsavelTarefaError || this.cancelarTarefaEquipeError ? html`<p class="mb-3 text-sm text-[var(--status-error-text,currentColor)]" role="alert">${this.msg.actionError} ${errorText(this.trocarResponsavelTarefaError) || errorText(this.cancelarTarefaEquipeError)}</p>` : ''}
          ${this.trocarResponsavelTarefaStatus === 'success' ? html`<p class="mb-3 text-sm text-[var(--status-success-text,currentColor)]" aria-live="polite">${this.msg.assigneeChanged}</p>` : ''}
          ${this.cancelarTarefaEquipeStatus === 'success' ? html`<p class="mb-3 text-sm text-[var(--status-success-text,currentColor)]" aria-live="polite">${this.msg.taskCancelled}</p>` : ''}
          <groupselectone--ml-select-one-autocomplete .value=${this.trocarResponsavelTarefaDraft.responsavelId} .placeholder=${this.msg.chooseAssignee} .loading=${this.buscarResponsaveisDisponiveisStatus === 'loading'} .disabled=${commandLoading} .clearable=${true} @focus=${() => this.buscarResponsaveisDisponiveis()} @change=${(e: CustomEvent<{ value: string | null }>) => this.setTrocarResponsavelTarefaDraft({ responsavelId: e.detail.value })}>
            <Label>${this.msg.newAssignee}</Label>
            ${this.buscarResponsaveisDisponiveisParticipantes.map((person) => html`<Item value=${person.id}>${person.details.identification.name}</Item>`)}
            <Empty>${this.msg.noEligibleAssignee}</Empty>
          </groupselectone--ml-select-one-autocomplete>
          <button type="button" class="mt-3 min-h-11 w-full rounded-lg bg-[var(--button-primary-bg,transparent)] px-4 font-semibold text-[var(--button-primary-text,currentColor)] focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)] disabled:opacity-50" ?disabled=${commandLoading || this.trocarResponsavelTarefaDraft.responsavelId === null} @click=${() => this.trocarResponsavelTarefa()}>${commandLoading ? this.msg.changingAssignee : this.msg.confirmChangeAssignee}</button>
          ${task.details.aberta ? html`<form class="mt-5 border-t border-[var(--border-subtle,currentColor)] pt-4" @submit=${(e: SubmitEvent) => { e.preventDefault(); const form = e.currentTarget; if (form instanceof HTMLFormElement && form.elements.namedItem('confirmCancel') instanceof HTMLInputElement && (form.elements.namedItem('confirmCancel') as HTMLInputElement).checked) this.cancelarTarefaEquipe(); }}><label class="flex min-h-11 items-center gap-2 text-sm"><input name="confirmCancel" type="checkbox" ?disabled=${commandLoading}>${this.msg.confirmCancellation}</label><button type="submit" class="mt-2 min-h-11 w-full rounded-lg bg-[var(--button-danger-bg,transparent)] px-4 font-semibold text-[var(--button-danger-text,currentColor)] focus-visible:ring-2 focus-visible:ring-[var(--focus-ring,currentColor)]" ?disabled=${commandLoading}>${commandLoading ? this.msg.cancellingTask : this.msg.confirmCancelTask}</button></form>` : ''}
        </div>
        <div class="mt-6" data-organism-id="tarefaHistorico"><h2 class="text-base font-semibold text-[var(--text-strong,currentColor)]">${this.msg.history}</h2><ol class="mt-3 space-y-3 border-l border-[var(--border-default,currentColor)] pl-4">${task.historico.length ? task.historico.map((event) => html`<li class="text-sm"><p class="font-medium">${event.tipo}</p><p class="text-xs text-[var(--text-muted,currentColor)]">${formatDate(event.momento)}${event.responsavelNome ? ` · ${this.msg.eventBy} ${event.responsavelNome}` : ''}</p>${event.details.motivoDevolucao ? html`<p class="mt-1 text-sm">${this.msg.returnReason}: ${event.details.motivoDevolucao}</p>` : ''}</li>`) : html`<li class="text-sm text-[var(--text-muted,currentColor)]">${this.msg.noHistory}</li>`}</ol></div>
      </section>
    `;
  }
}"}},"status":"completed","stepId":15,"interaction":null,"nextSteps":null}]

